acts = load('activities')
by = {a['id']: a for a in acts}
changed = 0
for aid, note in NOTES.items():
    a = by[aid]
    if 'התאמה לגילאים:' in a['guideNotes']:
        continue
    a['guideNotes'] = (a['guideNotes'].rstrip() + '\n\nהתאמה לגילאים: ' + note).strip()
    changed += 1
save('activities', acts)
wide = [a['id'] for a in acts if a['ageMax'] - a['ageMin'] >= 6]
missing = [i for i in wide if i not in NOTES]
print('updated', changed, 'wide', len(wide), 'missing', missing)
